    state.validate();const auto ticket=prepare_day(state);if(!owner.scope||owner.scope!=expected.scope||owner.revision!=expected.revision||owner.revision==UINT64_MAX||!state.friendly_plan||!state.progress||state.progress->phase!=ProgressPhase::scheduled_event||state.prepared_event||!state.desktop||state.desktop->active_seat||state.desktop->initial_event||!ticket||!ticket->leagues.empty()||!ticket->cups.empty()||!ticket->european.empty()||!ticket->national.empty()||!ticket->friendlies.empty()||!ticket->indoor.empty()||ticket->regional_playoff||ticket->others.empty()||std::any_of(ticket->others.begin(),ticket->others.end(),[](const auto& a){return !friendly_appointment(a);}))throw FormatError("world12: empty Source friendly date has no exact owner");
